import fs from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const redirects = JSON.parse(await fs.readFile(path.join(root, 'data/legacy-redirects.json'), 'utf8'))
const entries = Object.entries(redirects)

function tsString(value) {
  return `'${value.replaceAll('\\', '\\\\').replaceAll('\'', '\\\'')}'`
}

const nginxLines = [
  '# Generated by scripts/generate-redirects.mjs.',
  '# Include this file inside the wolfx.jp server block.',
  '# $is_args$args preserves an existing query string.',
  '',
]

const wolfxMcNginxLines = [
  '# Generated by scripts/generate-redirects.mjs.',
  '# Include this file inside the mc.wolfx.jp server block.',
  '# $is_args$args preserves an existing query string.',
  '',
]

for (const [source, target] of entries) {
  nginxLines.push(`location = ${source} {`)
  nginxLines.push(`    return 301 ${target}$is_args$args;`)
  nginxLines.push('}')
  nginxLines.push('')
}

for (const [source, target] of entries) {
  if (!source.startsWith('/mc/'))
    continue
  const publicSource = source.slice(3)
  const publicTarget = target.startsWith('/mc/') ? target.slice(3) : target
  wolfxMcNginxLines.push(`location = ${publicSource} {`)
  wolfxMcNginxLines.push(`    return 301 ${publicTarget}$is_args$args;`)
  wolfxMcNginxLines.push('}')
  wolfxMcNginxLines.push('')
}

const workerLines = [
  '// Generated by scripts/generate-redirects.mjs. Do not edit directly.',
  'export const legacyRedirects: Readonly<Record<string, string>> = {',
  ...entries.map(([source, target]) => `  ${tsString(source)}: ${tsString(target)},`),
  '}',
  '',
]

await fs.mkdir(path.join(root, 'deploy'), { recursive: true })
await fs.mkdir(path.join(root, 'worker'), { recursive: true })
await Promise.all([
  fs.writeFile(path.join(root, 'deploy/nginx-redirects.conf'), `${nginxLines.join('\n')}\n`),
  fs.writeFile(path.join(root, 'deploy/nginx-wolfxmc-redirects.conf'), `${wolfxMcNginxLines.join('\n')}\n`),
  fs.writeFile(path.join(root, 'worker/generated-redirects.ts'), workerLines.join('\n')),
])
console.log(`Generated ${entries.length} Nginx and Cloudflare permanent redirects.`)
